package data_model_test

import (
	"fmt"
	"testing"

	"github.com/VKCOM/statshouse/internal/data_model"
	"github.com/VKCOM/statshouse/internal/vkgo/basictl"
)

const chunkedMagicTest = 0x11223344

type TestModel struct {
	value uint32

	lastSavedVal uint32
}

func (tm *TestModel) addMapping() {
	tm.value++
}

func (tm *TestModel) load(storage *data_model.ChunkedStorage2) error {
	for {
		chunk, err := storage.ReadNext(chunkedMagicTest)
		if err != nil {
			return err
		}
		tm.lastSavedVal = tm.value
		if len(chunk) == 0 {
			break
		}
		if storage.IsFirst() {
			if chunk, err = basictl.NatReadExactTag(chunk, 0x123); err != nil {
				return fmt.Errorf("error parsing first chunk: %v", err)
			}
		}
		for len(chunk) != 0 {
			var nextVal uint32
			if chunk, err = basictl.NatRead(chunk, &nextVal); err != nil {
				return fmt.Errorf("error parsing test entry: %v", err)
			}
			if nextVal != tm.value+1 {
				return fmt.Errorf("unexpected test entry: %d (must be %d)", nextVal, tm.value)
			}
			tm.value++
		}
	}
	return nil
}

func (tm *TestModel) save(storage *data_model.ChunkedStorage2) (err error) {
	if tm.value <= tm.lastSavedVal {
		return nil
	}
	chunk := storage.StartWriteChunk(chunkedMagicTest, 0)
	if storage.IsFirst() {
		chunk = basictl.NatWrite(chunk, 0x123)
	}
	for ; tm.lastSavedVal < tm.value; tm.lastSavedVal++ {
		chunk = basictl.NatWrite(chunk, tm.lastSavedVal+1)
		if chunk, err = storage.FinishItem(chunk); err != nil {
			return err
		}
	}
	return storage.FinishWriteChunk(chunk)
}

func TestChunkedStorageSlice(t *testing.T) {
	var fp []byte
	storage := data_model.NewChunkedStorage2Slice(&fp)
	{
		var tm TestModel
		err := tm.load(storage)
		t.Logf("tm: %d %d err: %v\n", tm.value, tm.lastSavedVal, err)
		tm.addMapping()
		tm.addMapping()
		_ = tm.save(storage)
		_ = tm.save(storage)
		tm.addMapping()
		err = tm.save(storage)
		t.Logf("tm: %d %d err: %v\n", tm.value, tm.lastSavedVal, err)
	}
	storage = data_model.NewChunkedStorage2Slice(&fp)
	{
		var tm TestModel
		err := tm.load(storage)
		t.Logf("tm: %d %d err: %v\n", tm.value, tm.lastSavedVal, err)
		tm.addMapping()
		err = tm.save(storage)
		t.Logf("tm: %d %d err: %v\n", tm.value, tm.lastSavedVal, err)
	}
	storage = data_model.NewChunkedStorage2Slice(&fp)
	{
		var tm TestModel
		err := tm.load(storage)
		t.Logf("tm: %d %d err: %v\n", tm.value, tm.lastSavedVal, err)
	}
}

package api

import (
	"context"
	"testing"
	"time"

	"github.com/stretchr/testify/require"

	"github.com/VKCOM/statshouse/internal/data_model"
)

// Reproduces awaiter misdelivery: a loader that awaits a chunk being loaded
// by another loader, with a request range starting mid-chunk, receives no
// (or misplaced) data.
func TestCache2AwaiterOffset(t *testing.T) {
	h := &requestHandler{
		Handler: &Handler{
			HandlerOptions: HandlerOptions{
				location: time.Local,
			},
		},
	}
	firstLoadEntered := make(chan struct{})
	releaseFirstLoad := make(chan struct{})
	loadN := 0
	c := newCache2(h.Handler, 0, func(_ context.Context, _ *requestHandler, _ *queryBuilder, lod data_model.LOD, ret [][]tsSelectRow, _ int) (int, error) {
		loadN++
		if loadN == 1 {
			close(firstLoadEntered)
			<-releaseFirstLoad
		}
		for i := 0; i < len(ret); i++ {
			ret[i] = []tsSelectRow{{time: lod.FromSec + int64(i)*lod.StepSec}}
		}
		return len(ret), nil
	})
	defer c.shutdown()

	// chunk grid: 60s chunks at 1s step
	base := (time.Now().Unix() / 60) * 60
	lodA := data_model.LOD{Version: Version6, StepSec: 1, FromSec: base, ToSec: base + 60}
	lodB := data_model.LOD{Version: Version6, StepSec: 1, FromSec: base + 30, ToSec: base + 60}

	q := &queryBuilder{}
	resA := make(chan error, 1)
	go func() {
		_, err := c.Get(context.Background(), h, q, lodA, false)
		resA <- err
	}()
	<-firstLoadEntered // loader A is now loading chunk [base, base+60)

	resB := make(chan cache2Data, 1)
	errB := make(chan error, 1)
	go func() {
		data, err := c.Get(context.Background(), h, q, lodB, false)
		resB <- data
		errB <- err
	}()
	// wait until B registered itself as awaiter on the chunk
	require.Eventually(t, func() bool {
		shard := c.shards[time.Second]
		shard.mu.Lock()
		defer shard.mu.Unlock()
		for _, b := range shard.bucketM {
			b.mu.Lock()
			for _, chunk := range b.chunks {
				chunk.mu.Lock()
				n := len(chunk.awaiters)
				chunk.mu.Unlock()
				if n > 0 {
					b.mu.Unlock()
					return true
				}
			}
			b.mu.Unlock()
		}
		return false
	}, 5*time.Second, time.Millisecond)

	close(releaseFirstLoad)
	require.NoError(t, <-resA)
	data := <-resB
	require.NoError(t, <-errB)

	// B asked for [base+30, base+60): 30 slots, each must contain
	// exactly one row with the matching timestamp
	require.Len(t, data, 30)
	for i := 0; i < len(data); i++ {
		require.Len(t, data[i], 1, "slot %d has no data", i)
		require.Equal(t, lodB.FromSec+int64(i), data[i][0].time, "slot %d has wrong timestamp", i)
	}
}

package api

import (
	"context"
	"testing"
	"time"

	"github.com/stretchr/testify/require"
	"pgregory.net/rand"
	"pgregory.net/rapid"

	"github.com/VKCOM/statshouse/internal/data_model"
)

func TestCache2BucketList(t *testing.T) {
	s := [100]cache2Bucket{}
	l := newCache2BucketList()
	require.Equal(t, 0, l.len())
	for i := 0; i < len(s); i++ {
		l.add(&s[i])
		require.Equal(t, i+1, l.len())
	}
	for i := 0; i < len(s); i++ {
		l.remove(&s[i])
		require.Equal(t, len(s)-i-1, l.len())
	}
}

func TestCache2TrimBucketHeapMaxSize(t *testing.T) {
	rapid.Check(t, func(t *rapid.T) {
		h := make(cache2TrimBucketHeap, 0, 10)
		for i := 0; i < 10; i++ {
			h = h.push(cache2TrimBucket{info: cache2BucketRuntimeInfo{
				size: rapid.Int().Draw(t, "sizeInBytes"),
			}})
		}
		sizeInBytes := h.min().info.size
		for h.len() > 1 {
			h = h.pop()
			require.GreaterOrEqual(t, sizeInBytes, h.min().info.size)
			sizeInBytes = h.min().info.size
		}
		h = h.pop()
		require.Zero(t, h.len())
	})
}

func TestCache2TrimBucketHeapMinAccessTime(t *testing.T) {
	rapid.Check(t, func(t *rapid.T) {
		h := make(cache2TrimBucketHeap, 0, 1000)
		for i := 0; i < 1000; i++ {
			h = h.push(cache2TrimBucket{info: cache2BucketRuntimeInfo{
				idlePeriod: time.Duration(rapid.Int64().Draw(t, "lastAccessTime")),
			}})
		}
		lastAccessTime := h.min().info.idlePeriod
		for h.len() > 1 {
			h = h.pop()
			require.GreaterOrEqual(t, lastAccessTime, h.min().info.idlePeriod)
			lastAccessTime = h.min().info.idlePeriod
		}
		h = h.pop()
		require.Zero(t, h.len())
	})
}

func TestCache2TrimBucketHeapMaxPlay(t *testing.T) {
	rapid.Check(t, func(t *rapid.T) {
		h := make(cache2TrimBucketHeap, 0, 1000)
		for i := 0; i < 1000; i++ {
			h = h.push(cache2TrimBucket{info: cache2BucketRuntimeInfo{
				playInterval: time.Duration(rapid.Int64().Draw(t, "play")),
			}})
		}
		play := h.min().info.playInterval
		for h.len() > 1 {
			h = h.pop()
			require.GreaterOrEqual(t, play, h.min().info.playInterval)
			play = h.min().info.playInterval
		}
		h = h.pop()
		require.Zero(t, h.len())
	})
}

func TestCache2AddRemoveChunks(t *testing.T) {
	h := &requestHandler{
		Handler: &Handler{
			HandlerOptions: HandlerOptions{
				location: time.Local,
			},
		},
	}
	q := &queryBuilder{}
	c := newCache2(h.Handler, 0, nil)
	shard := c.shards[time.Second]
	info := cache2UpdateInfo{}
	b := shard.getOrCreateLockedBucket(h, q, &info)
	b.mu.Unlock()
	c.updateRuntimeInfo(shard.stepS, b.fau, &info)
	rapid.Check(t, func(t *rapid.T) {
		// add chunks
		lenG := rapid.IntRange(0, 32)
		timeNow := time.Now()
		timeG := rapid.Int64Range(timeNow.Add(-24*time.Hour).Unix(), timeNow.Unix())
		for i := 0; i < 512; i++ {
			start := timeG.Draw(t, "from sec")
			l := cache2Loader{
				cache:   c,
				handler: h,
				query:   q,
				shard:   shard,
				bucket:  b,
				lod: data_model.LOD{
					FromSec: start,
					ToSec:   start + int64(lenG.Draw(t, "chunk length")),
				},
			}
			info := cache2UpdateInfo{}
			l.init(&info)
			c.updateRuntimeInfo(shard.stepS, b.fau, &info)
		}
		// acccess chunks
		for _, chunk := range b.chunks {
			chunk.lastAccessTime = timeG.Draw(t, "chunk last access time")
		}
		// remove chunks
		for n := len(b.chunks); n != 0; n = len(b.chunks) {
			i := rapid.IntRange(0, n-1).Draw(t, "chunk index")
			info := cache2UpdateInfo{}
			b.removeChunksNotUsedAfterUnlocked(b.chunks[i].lastAccessTime+1, &info)
			c.updateRuntimeInfo(shard.stepS, b.fau, &info)
			require.Less(t, len(b.chunks), n)
		}
	})
	c.shutdown().Wait()
	require.Zero(t, c.info.size())
}

func TestCache2Parallel(t *testing.T) {
	h := &requestHandler{
		Handler: &Handler{
			HandlerOptions: HandlerOptions{
				location: time.Local,
			},
		},
	}
	c := newCache2(h.Handler, 0, func(_ context.Context, _ *requestHandler, _ *queryBuilder, _ data_model.LOD, ret [][]tsSelectRow, _ int) (int, error) {
		for i := 0; i < len(ret); i++ {
			ret[i] = make([]tsSelectRow, rand.Intn(2))
		}
		return len(ret), nil
	})
	c.setLimits(cache2Limits{maxSize: 32})
	requireCache2Valid(t, c)
	t.Run("parent", func(t *testing.T) {
		for i := 0; i < 128; i++ {
			t.Run("child", func(t *testing.T) {
				t.Parallel()
				q := &queryBuilder{
					play: rand.Intn(15),
				}
				for i := 0; i < 512; i++ {
					lod := cache2TestDrawLOD(c)
					_, err := c.Get(context.Background(), h, q, lod, false)
					require.NoError(t, err)
				}
			})
		}
	})
	c.shutdown().Wait()
	c.mu.Lock()
	defer c.mu.Unlock()
	requireCache2Valid(t, c)
	c.info.normalizeWaterLevel()
	c.info.resetAccessInfo()
	require.Equal(t, c.info, cache2RuntimeInfo{minChunkAccessTime: c.info.minChunkAccessTime})
}

func cache2TestDrawLOD(c *cache2) data_model.LOD {
	n := rand.Intn(len(c.shards) - 1)
	var shard *cache2Shard
	for _, v := range c.shards {
		if v.step != timeMonth && n <= 0 {
			shard = v
			break
		}
		n--
	}
	start := rand.Int63n(time.Now().UnixNano())
	start = (start / int64(shard.step)) * int64(shard.step) // align
	end := start + int64(shard.step)*rand.Int63n(10)
	return data_model.LOD{
		Version: Version6,
		StepSec: int64(shard.step / time.Second),
		FromSec: start / int64(time.Second),
		ToSec:   end / int64(time.Second),
	}
}

func requireCache2Valid(t *testing.T, c *cache2) {
	for _, shard := range c.shards {
		requireCache2ShardValid(t, shard)
	}
}

func requireCache2ShardValid(t *testing.T, shard *cache2Shard) {
	for _, b := range shard.bucketM {
		requireCache2BucketValid(t, b)
	}
}

func requireCache2BucketValid(t *testing.T, b *cache2Bucket) {
	require.Equal(t, len(b.times), len(b.chunks))
	if len(b.times) == 0 {
		return
	}
	require.Equal(t, b.times[0], b.chunks[0].start)
	for i := 1; i < len(b.times); i++ {
		require.Less(t, b.times[i-1], b.times[i])
		require.Equal(t, b.times[i], b.chunks[i].start)
	}
}

package api

import (
	"context"
	"testing"
	"time"

	"github.com/stretchr/testify/require"

	"github.com/VKCOM/statshouse/internal/data_model"
)

// Reproduces stale reads from pointsCache: cacheEntry.loadedAtNano is shared
// across time ranges of the same query, so loading range B "revalidates"
// range A's rows that were loaded before an invalidation.
func TestPointsCacheStaleAfterOtherRangeLoad(t *testing.T) {
	now := time.Now()
	nowF := func() time.Time { return now }
	generation := 0
	loader := func(_ context.Context, _ *requestHandler, _ *queryBuilder, _ data_model.LOD) ([]pSelectRow, error) {
		return []pSelectRow{{tsValues: tsValues{count: float64(generation)}}}, nil
	}
	c := newPointsCache(1000, 0, loader, nowF)
	h := &requestHandler{Handler: &Handler{}}
	q := &queryBuilder{}

	base := now.Unix() - 3600 // within the mutable 48h window
	lodA := data_model.LOD{FromSec: base, ToSec: base + 60}
	lodB := data_model.LOD{FromSec: base + 120, ToSec: base + 180}

	// load range A (generation 0)
	generation = 0
	rows, err := c.get(context.Background(), h, q, lodA, false)
	require.NoError(t, err)
	require.Equal(t, float64(0), rows[0].count)

	// data for a second inside range A changes; invalidation arrives
	now = now.Add(time.Second)
	c.invalidate([]int64{base + 30})
	generation = 1 // fresh data available from now on

	// immediately after invalidation, range A correctly misses cache
	_, ok := c.loadCached(q.getOrBuildCacheKey(), lodA.FromSec, lodA.ToSec)
	require.False(t, ok, "range A must be invalid right after invalidation")

	// more than invalidateLinger later, someone queries range B (same query key)
	now = now.Add(invalidateLinger + time.Second)
	_, err = c.get(context.Background(), h, q, lodB, false)
	require.NoError(t, err)

	// range A must still read as invalid: its rows were loaded before the
	// invalidation. Before the fix, B's load refreshed a shared loadedAtNano
	// and range A was served as fresh (returning pre-invalidation data).
	rows, ok = c.loadCached(q.getOrBuildCacheKey(), lodA.FromSec, lodA.ToSec)
	require.False(t, ok, "stale rows served: range A revalidated by range B's load, count=%v", rows[0].count)
}

package api

import (
	"testing"
	"time"

	"github.com/stretchr/testify/require"
	"pgregory.net/rapid"
)

type secondCacheSimple struct {
	sec map[int64]int64
	now func() time.Time
}

func (c *secondCacheSimple) updateTime(invalidatedAtNano, sec int64) {
	c.sec[sec] = invalidatedAtNano
}

func (c *secondCacheSimple) checkInvalidation(loadAt, from, to int64) bool {
	now := c.now()
	cacheImmutable := now.Add(invalidateFrom)
	if time.Unix(from, 0).Before(cacheImmutable) {
		from = cacheImmutable.Unix()
	}
	if time.Unix(to, 0).Before(cacheImmutable) {
		return true
	}
	for s, at := range c.sec {
		if s >= from && s <= to && loadAt <= at+int64(invalidateLinger) {
			return false
		}
	}
	return true
}

type cacheTestState struct {
	cache       *invalidatedSecondsCache
	cacheSimple *secondCacheSimple
	currentTime int64
}

func (s *cacheTestState) init(t *rapid.T) {
	s.currentTime = 100_000_000
	now := func() time.Time {
		return time.Unix(s.currentTime, 0)
	}
	s.cache = newSecondsCache(0, now)
	s.cacheSimple = &secondCacheSimple{sec: map[int64]int64{}, now: now}
}
func (s *cacheTestState) Tick(r *rapid.T) {
	s.currentTime++
}

func (s *cacheTestState) Push(r *rapid.T) {
	max := s.currentTime
	loadedAtNano := time.Unix(max, 0).UnixNano()
	invalidatedSec := int64(invalidateFrom.Abs().Seconds())
	sec := rapid.Int64Range(max-1-invalidatedSec, max-1).Draw(r, "invalidated sec")
	s.cache.updateTimeLocked(loadedAtNano, sec)
	s.cacheSimple.updateTime(loadedAtNano, sec)
}

func (s *cacheTestState) CheckInvalidation(r *rapid.T) {
	max := s.currentTime
	rang := int64((30 * 24 * time.Hour).Seconds())
	from := rapid.Int64Range(max-rang, max-1).Draw(r, "from")
	to := rapid.Int64Range(from+1, max).Draw(r, "to")
	loadedAtRange := int64(invalidateFrom.Abs().Seconds())
	loadedAt := rapid.Int64Range(max-loadedAtRange, max).Draw(r, "loaded_at")
	loadedAtNano := time.Unix(loadedAt, 0).UnixNano()
	expected := s.cacheSimple.checkInvalidation(loadedAtNano, from, to)
	got := s.cache.checkInvalidationLocked(loadedAtNano, from, to)
	require.Equal(r, expected, got)
}

func (s *cacheTestState) Check(r *rapid.T) {

}

func TestSecondsCache(t *testing.T) {
	rapid.Check(t, func(t *rapid.T) {
		m := cacheTestState{}
		m.init(t)
		t.Repeat(rapid.StateMachineActions(&m))
	})
}

